package com.yihe.framework.ehr;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;
@Service
public class OccupationalArchiveService {
 final EhrRepository db;final EhrService ehr;final EmployeeHealthArchiveService employees;
 public OccupationalArchiveService(EhrRepository db,EhrService ehr,EmployeeHealthArchiveService employees){this.db=db;this.ehr=ehr;this.employees=employees;}
 String table(){return "a_occupational_archive_versions";}
 boolean occupational(){return true;}
 static final List<String> FIELDS=Arrays.asList("dueDate","hireDate","surveillanceCategory","exposureSince","protection","exposureLevel","exposureNotes","assessmentNote");
 void allow(EhrActor a){require(!a.mobile,403,"请使用企业管理端访问监护档案");}
 Map<String,Object> source(EhrActor a,String record){Map<String,Object> p=employees.detail(a,record);p.remove("logs");p.remove("serviceTasks");p.remove("followups");
 p.put("occupationalFields",db.all("SELECT o.field_key fieldKey,o.original_field_name label,o.value_raw value,o.review_status reviewStatus,o.report_id reportId,o.revision,e.source_file_id sourceId,e.page_number page FROM a_occupational_profiles o JOIN a_health_reports h ON h.report_id=o.report_id AND h.revision=o.revision JOIN a_report_series s ON s.report_id=h.report_id AND s.current_revision=h.revision LEFT JOIN a_report_evidence e ON e.evidence_id=o.evidence_id AND e.report_id=o.report_id AND e.revision=o.revision WHERE h.record_id=? AND h.scope_code=? AND h.data_mode=? AND o.scope_code=? AND o.data_mode=? ORDER BY h.created_at DESC,o.field_key,o.profile_id",record,a.scope,a.mode,a.scope,a.mode));return p;}
 Object canonical(Object o){if(o instanceof Map){Map<String,Object> m=new TreeMap<>();((Map<?,?>)o).forEach((k,v)->m.put(String.valueOf(k),canonical(v)));return m;}if(o instanceof List){List<Object> x=new ArrayList<>();for(Object v:(List<?>)o)x.add(canonical(v));return x;}return o;}
 String hash(Object o){return hex(digest(bytes(ehr.encode(canonical(o)))));}
 Map<String,Object> latest(EhrActor a,String record){return db.one("SELECT * FROM "+table()+" WHERE scope_code=? AND data_mode=? AND record_id=? ORDER BY revision DESC LIMIT 1",a.scope,a.mode,record);}
 Map<String,Object> empty(){Map<String,Object> m=map("template","standard");for(String k:FIELDS)m.put(k,"");for(String k:Arrays.asList("diagnoses","events","diseaseCases"))m.put(k,new ArrayList<>());return m;}
 @SuppressWarnings("unchecked") public Map<String,Object> detail(EhrActor a,String record,Integer revision){allow(a);ehr.profile(a,record,false);Map<String,Object> facts=source(a,record),last=latest(a,record),selected=last;if(revision!=null&&revision>0){selected=db.one("SELECT * FROM "+table()+" WHERE scope_code=? AND data_mode=? AND record_id=? AND revision=?",a.scope,a.mode,record,revision);require(selected!=null,404,"监护档案版本不存在");}
 Map<String,Object> document=selected==null?empty():(Map<String,Object>)ehr.decode(selected.get("document_json"));
 return map("employee",selected==null||num(selected.get("revision"))==num(last.get("revision"))?facts:ehr.decode(selected.get("source_snapshot_json")),"document",document,"version",selected==null?0:selected.get("revision"),"currentVersion",last==null?0:last.get("revision"),"status",selected==null?"unfiled":selected.get("document_status"),"sourceDigest",hash(facts),"savedSourceDigest",selected==null?null:selected.get("source_digest"),"sourceChanged",selected!=null&&!hash(facts).equals(selected.get("source_digest")),"actor",selected==null?null:selected.get("actor_ref"),"note",selected==null?null:selected.get("action_note"),"confirmationSourceId",selected==null?null:selected.get("confirmation_source_id"),"createdAt",selected==null?null:selected.get("created_at"),"canEdit",a.doctor,"candidateOnly",ehr.candidateOnly,"versions",db.all("SELECT revision,document_status status,action_name action,actor_ref actor,action_note note,created_at createdAt FROM "+table()+" WHERE scope_code=? AND data_mode=? AND record_id=? ORDER BY revision DESC LIMIT 100",a.scope,a.mode,record));}
 void sourceFile(EhrActor a,String record,String source){require(source.matches("[a-fA-F0-9-]{36}"),422,"请提供有效来源原件");require(db.count("SELECT COUNT(*) FROM a_report_revision_sources s JOIN a_health_reports h ON h.report_id=s.report_id AND h.revision=s.revision WHERE h.record_id=? AND h.scope_code=? AND h.data_mode=? AND s.source_file_id=?",record,a.scope,a.mode,source)>0,422,"来源原件不属于当前职工档案");}
 @SuppressWarnings("unchecked") Map<String,Object> document(EhrActor a,String record,Object raw){require(raw instanceof Map,422,"请提供监护档案表单");Map<?,?> input=(Map<?,?>)raw;Set<String> allowed=new HashSet<>(FIELDS);allowed.addAll(Arrays.asList("template","diagnoses","events","diseaseCases"));for(Object k:input.keySet())require(allowed.contains(k),422,"表单含不支持的字段");Map<String,Object> d=empty();String template=str(input.get("template"));require(Arrays.asList("standard","exposure","followup").contains(template),422,"模板无效");d.put("template",template);
 for(String k:FIELDS){Object value=input.get(k);require(value==null||value instanceof String,422,"表单字段应为文本");String text=str(value).trim();require(text.length()<=1500,422,"表单字段超过长度限制");if(!text.isEmpty()&&k.equals("dueDate")){try{java.time.LocalDate deadline=java.time.LocalDate.parse(text);require(deadline.getYear()>=1900&&deadline.getYear()<=2100,422,"办理期限日期无效");}catch(java.time.format.DateTimeParseException invalid){throw new EhrException(422,"办理期限日期无效");}}else if(Arrays.asList("hireDate","exposureSince").contains(k)&&!text.isEmpty())ehr.date(text);d.put(k,text);}
 Map<String,List<String>> rows=new LinkedHashMap<>();rows.put("diagnoses",Arrays.asList("date","diagnosis","treatment","status","sourceId"));rows.put("events",Arrays.asList("date","type","measure","result","sourceId"));rows.put("diseaseCases",Arrays.asList("matter","date","conclusion","handling","sourceId"));
 for(Map.Entry<String,List<String>> group:rows.entrySet()){Object value=input.get(group.getKey());require(value instanceof List&&((List<?>)value).size()<=50,422,"每组最多50条记录");List<Object> result=new ArrayList<>();for(Object row:(List<?>)value){require(row instanceof Map,422,"记录格式无效");Map<?,?> values=(Map<?,?>)row;Map<String,Object> item=new LinkedHashMap<>();for(Object k:values.keySet())require(group.getValue().contains(k),422,"记录含不支持字段");for(String key:group.getValue()){Object v=values.get(key);require(v==null||v instanceof String,422,"记录字段应为文本");String text=str(v).trim();require(text.length()<=1000,422,"记录文本过长");if(key.equals("date")&&!text.isEmpty())ehr.date(text);item.put(key,text);}sourceFile(a,record,str(item.get("sourceId")));require(item.values().stream().filter(v->!str(v).isEmpty()).count()>1,422,"记录内容不能为空");result.add(item);}d.put(group.getKey(),result);}require(ehr.encode(d).length()<=100000,422,"表单内容过长");return d;}
 @Transactional @SuppressWarnings("unchecked") public Map<String,Object> act(EhrActor a,String record,Map<String,Object> body){allow(a);require(a.doctor,403,"仅授权医生可保存、登记确认或审核监护档案");ehr.profile(a,record,true);db.all("SELECT h.report_id,h.revision FROM a_health_reports h JOIN a_report_series s ON s.report_id=h.report_id AND s.current_revision=h.revision WHERE h.record_id=? AND h.scope_code=? AND h.data_mode=? FOR UPDATE",record,a.scope,a.mode);String action=text(body,"action"),key=text(body,"requestKey"),note=text(body,"note").trim();require(Arrays.asList("save","submit","confirm","review","archive").contains(action),422,"不支持的操作");require(key.matches("[a-fA-F0-9-]{36}"),422,"操作幂等键无效");require(!note.isEmpty()&&note.length()<=1000,422,"请填写处理依据，最多1000字");String payload=hash(body);Map<String,Object> receipt=db.one("SELECT record_id,payload_digest,revision FROM "+table()+" WHERE scope_code=? AND data_mode=? AND request_key=?",a.scope,a.mode,key);if(receipt!=null){require(record.equals(receipt.get("record_id"))&&payload.equals(receipt.get("payload_digest")),409,"操作键已用于其他内容");return detail(a,record,num(receipt.get("revision")));}
 Map<String,Object> previous=latest(a,record),facts=source(a,record);int current=previous==null?0:num(previous.get("revision"));require(body.get("expectedRevision") instanceof Number&&num(body.get("expectedRevision"))==current,409,"档案已有新版本，请刷新后重试");String sourceDigest=hash(facts);require(sourceDigest.equals(text(body,"sourceDigest")),409,"关联资料已变化，请刷新后重新核对");Map<String,Object> doc;String state;String confirmation=null;
 if(action.equals("save")){doc=document(a,record,body.get("document"));state="draft";}else{require(previous!=null,422,"请先保存档案表单");require(sourceDigest.equals(previous.get("source_digest")),409,"保存后原始资料已变化，请重新核对并保存");doc=(Map<String,Object>)ehr.decode(previous.get("document_json"));if(action.equals("submit")){require(Arrays.asList("draft").contains(str(previous.get("document_status"))),409,"请先保存待提交草稿");require(!str(facts.get("name")).isEmpty()&&!str(facts.get("code")).isEmpty(),422,"姓名、工号不能为空");require(!((List<?>)facts.get("reports")).isEmpty(),422,"请先关联报告原件");require(!occupational()||!str(doc.get("hireDate")).isEmpty()&&!str(doc.get("surveillanceCategory")).isEmpty(),422,"请填写入职日期和监护类别");state="pending_employee";}else if(action.equals("archive")){require(!ehr.candidateOnly,403,"当前环境不允许表单归档");require("reviewed".equals(previous.get("document_status")),422,"请先完成医生审核");require(Boolean.TRUE.equals(body.get("archiveVerified")),422,"请确认表单归档内容与版本");confirmation=str(previous.get("confirmation_source_id"));state="archived";}else if(action.equals("confirm")){require(Arrays.asList("draft","pending_employee").contains(str(previous.get("document_status"))),409,"仅待确认版本可登记职工确认");require(Boolean.TRUE.equals(body.get("evidenceVerified")),422,"请核对职工本人确认材料");confirmation=text(body,"sourceId");sourceFile(a,record,confirmation);state="employee_confirmed";}else{require(!ehr.candidateOnly,403,"当前环境不允许审核确认");require("employee_confirmed".equals(previous.get("document_status")),422,"请先登记职工确认材料");require(Boolean.TRUE.equals(body.get("identityVerified"))&&Boolean.TRUE.equals(body.get("contentVerified")),422,"请完成身份与原件核对");require(!occupational()||!str(doc.get("surveillanceCategory")).isEmpty(),422,"请先填写监护类别");List<?> reports=(List<?>)facts.get("reports");require(!reports.isEmpty()&&reports.stream().allMatch(r->"confirmed".equals(((Map<?,?>)r).get("reviewStatus"))),422,"请先在档案审核与归档中审核关联报告");confirmation=str(previous.get("confirmation_source_id"));state="reviewed";}}
 db.insert(table(),map("scope_code",a.scope,"data_mode",a.mode,"record_id",record,"revision",current+1,"document_json",ehr.encode(doc),"source_snapshot_json",ehr.encode(facts),"source_digest",sourceDigest,"document_status",state,"action_name",action,"actor_ref",a.user,"action_note",note,"confirmation_source_id",confirmation,"request_key",key,"payload_digest",payload,"created_at",now()));ehr.audit(a,record,null,null,(occupational()?"occupational_archive_":"general_archive_")+action,"监护档案V"+(current+1)+"；"+note);return detail(a,record,current+1);}
}
